banana.pixel:
uniform sampler2D uTexture;
in vec2 sg_uv;
layout(location=0) out vec4 fragColor[TD_NUM_COLOR_BUFFERS];
void main() {
    TDCheckDiscard();
    vec2 sg_n_uv = sg_uv;
    vec4 sg_n_texture = texture(uTexture, sg_n_uv);
    vec4 sg_color = sg_n_texture;
    TDAlphaTest(sg_color.a);
    fragColor[0] = TDOutputSwizzle(TDDither(sg_color));
}

banana.vertex:
uniform sampler2D uTexture;
out vec2 sg_uv;
void main() {
    sg_uv = TDTexCoord(0u).xy;
    vec3 sg_n_position = TDPos();
    vec4 sg_n_deform = TDDeform(sg_n_position);
    vec4 sg_n_projection = TDWorldToProj(sg_n_deform);
    gl_Position = sg_n_projection;
}

